from typing import List

def has_close_elements(numbers: List[float], threshold: float) -> bool:
    """
    Return True if any two numbers in `numbers` are closer than `threshold`.
    """
    if len(numbers) < 2:
        return False
    numbers_sorted = sorted(numbers)
    for i in range(1, len(numbers_sorted)):
        if abs(numbers_sorted[i] - numbers_sorted[i - 1]) < threshold:
            return True
    return False

def polynomial_to_string(n: int, coeffs: list[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (list[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign and absolute coefficient
        sign = '-' if coeff < 0 else '+'
        abs_coeff = abs(coeff)

        # Build coefficient string
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Build variable part
        if degree > 1:
            var_part = f'x^{degree}'
        elif degree == 1:
            var_part = 'x'
        else:
            var_part = ''

        term = coeff_str + var_part
        if not term:  # Handle case when both coeff_str and var_part are empty (shouldn't happen)
            term = '0'

        # Add sign for first term
        if not terms:
            if sign == '-':
                term = '-' + term
        else:
            term = sign + term
        terms.append(term)

    if not terms:
        return '0'

    return ''.join(terms)

